import{z as s,x as B,o as t,c as D,q as i,j as r,D as a,d as n,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"合成对照的深化","description":"","frontmatter":{"title":"合成对照的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-synthetic-control-deep.md","filePath":"econ/pe-synthetic-control-deep.md","lastUpdated":1791413859000}'),d={name:"econ/pe-synthetic-control-deep.md"};function p(h,e,c,m,u,C){const A=B("Mermaid");return t(),D("div",null,[e[2]||(e[2]=i('<h1 id="合成对照的深化" tabindex="-1">合成对照的深化 <a class="header-anchor" href="#合成对照的深化" aria-label="Permalink to &quot;合成对照的深化&quot;">​</a></h1><div class="epigraph"><p>合成对照的深化不是换一套软件，而是换一套承诺：把「拟合得好」从结果改成前提，把推断从分布改成设计——前提塌了，点估计再漂亮也是噪声。</p><footer>—— 据 Abadie, Using Synthetic Controls: Feasibility, Data Requirements, and Methodological Aspects, JEL 2021；Arkhangelsky, Athey, Hirshberg, Imbens and Wager, AER 2021 整理</footer></div><p><a href="/econ/cb-independence-history">上一课</a>把经济史对照收在央行独立性上：2008 与欧债把最后贷款人扩到影子链与主权，财政主导可以吞掉法律独立，独立性指数不是充分统计。经济主干至此走完，本课开「政策评估深化」的深钻层。本课回到<a href="/econ/synthetic-control">合成控制</a>：那里钉了凸权重、禁外推与安慰剂排列，缺口是它何时<strong>可行</strong>、偏差在哪、修正方法各付什么代价。本课程之后依次过事件研究的规范、交错修正、断点与工具、RCT，最后落到决策与证据综合。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/synthetic-control">合成控制</a>给了装置：对照库上的凸组合贴处理前路径，处理后缺口即效应。Abadie 2021 把使用条件收成一张<strong>可行判据</strong>清单。其一，处理前拟合必须好——这不是奖励，是前提：拟合差说明对照库张不出 \\(\\hat Y_1(0)\\)，是设计失败，不是效应为零。其二，处理单位要落在对照库凸包内，水平与趋势都不是极端点；凸包之外不存在合格合成，负权重回归是把外推伪装成对照。其三，处理期内不能有只打处理单位的<strong>同时冲击</strong>：合成对照把处理后一切偏离都读成干预，区分不了干预与特异冲击。其四，\\(T_0\\) 要够长——预测变量相对处理前期太多时，好拟合可以纯靠记忆噪声堆出来。</p><p><span class="marginnote">直觉类比：凸组合像调色盘混色——给对照库每个单位一个非负权重、加总为一，调出处理单位的「颜色」（水平与趋势）。处理单位若落在凸包内，总能调出近似色；若它本身是极端点（颜色在调色盘之外），无论怎么配都调不出，允许负权重等于往调色盘里加「不存在的颜料」——外推，不是对照。</span></p><h3 id="修正方法与其代价" tabindex="-1">修正方法与其代价 <a class="header-anchor" href="#修正方法与其代价" aria-label="Permalink to &quot;修正方法与其代价&quot;">​</a></h3><p>两个方向补基本装置的洞。augmented synthetic control（Ben-Michael、Feller 与 Rothstein）对处理前缺口再做一次回归修正，是双重稳健式的偏差校正：权重选不满时用回归垫层，代价是把外推重新请回来。synthetic DiD（Arkhangelsky 等）同时放单位权重与时间权重，在「只靠拟合」（合成控制，怕 \\(T_0\\) 短）与「只靠平行趋势」（DiD，怕趋势不平行）之间插值，代价是要求有多个处理单位。</p><p><span class="marginnote">Abadie 2021 把「预测变量多、\\(T_0\\) 短」列为高发伤：拟合优度会虚高。拟合图因此要当前提证明来读，不是当效应证据——拟合好只证明装置能动，不证明缺口是效应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实施顺序固定。第一步定对照库：剔除可能受溢出的单位（烟税案例里的邻州走私），只留同制度、同数据质量的对象。第二步报凸包判据与处理前拟合，不合格即停。第三步选修正：单处理单位、\\(T_0\\) 长，基本合成加安慰剂；多处理单位或 \\(T_0\\) 短，上 synthetic DiD 或 augmented。第四步推断：单单位没有常规标准误，安慰剂排列——把假处理派给对照单位，看真实缺口的 RMSPE 排位——是最小装置；时序口径可接共形推断。<span class="marginnote">数字实例：把假处理轮流派给 30 个对照单位，各自算出处理前后缺口；若真实缺口排在第 3 大，排位就是 \\(3/30\\)——真实效应比 90% 的「假效应」都大。这是排位，不是 \\(p\\) 值：它不承诺在零假设下均匀分布，只承诺设计层面的可比性。</span>流程之外不做第五种变体。</p>',11)),(t(),r(l,null,{default:a(()=>[o(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%AE%9A%E5%AF%B9%E7%85%A7%E5%BA%93%3A%20%E5%89%94%E9%99%A4%E6%BA%A2%E5%87%BA%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20FIT%5B%22%E6%8A%A5%E5%91%8A%E5%A4%84%E7%90%86%E5%89%8D%E6%8B%9F%E5%90%88%22%5D%0A%20%20FIT%20--%3E%20HULL%7B%22%E5%A4%84%E7%90%86%E5%8D%95%E4%BD%8D%E5%9C%A8%E5%87%B8%E5%8C%85%E5%86%85%3F%22%7D%0A%20%20HULL%20--%3E%7C%E5%90%A6%7C%20STOP%5B%22%E6%97%A0%E5%90%88%E6%A0%BC%E5%90%88%E6%88%90%3A%20%E5%81%9C%22%5D%0A%20%20HULL%20--%3E%7C%E6%98%AF%7C%20AUG%7B%22%E5%8D%95%E4%BD%8D%E6%95%B0%E4%B8%8E%20T0%3F%22%7D%0A%20%20AUG%20--%3E%7C%E5%8D%95%E5%8D%95%E4%BD%8D%E4%B8%94%20T0%20%E9%95%BF%7C%20PLAC%5B%22%E5%9F%BA%E6%9C%AC%E5%90%88%E6%88%90%E5%8A%A0%E5%AE%89%E6%85%B0%E5%89%82%E6%8E%92%E5%88%97%22%5D%0A%20%20AUG%20--%3E%7C%E5%A4%9A%E5%8D%95%E4%BD%8D%E6%88%96%20T0%20%E7%9F%AD%7C%20SDID%5B%22synthetic%20DiD%20%E6%88%96%20augmented%20%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20PLAC%20--%3E%20INF%5B%22%E7%BC%BA%E5%8F%A3%E6%8E%92%E4%BD%8D%E4%BD%9C%E4%B8%BA%E6%8E%A8%E6%96%AD%22%5D%0A%20%20SDID%20--%3E%20INF%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,"机制是把「对照」从平均改为加权：凸权重同时吸收单位固定效应与低阶共同趋势，于是平行趋势假设被换成「对照库能张成处理单位的 \\(Y(0)\\) 路径」这一更可检验的陈述。偏差的两个来源对应两个修正：过拟合与 \\(T_0\\) 短由 synthetic DiD 的时间权重吸收；权重压不到零（凸包边缘）由 augmented 的回归垫层吸收。两个修正都在基本装置吃紧时才值得启动——拟合本就好的案例硬上修正，是用方差换一个不存在的偏误。",-1)),e[5]||(e[5]=E("p",null,"不这么做会错在哪：把安慰剂排位当 \\(p\\) 值解释（它是设计检验，不是检验水平）；把拟合图当证据正文（它是前提证明）；给单单位缺口配常规聚类标准误（没有这样的分布理论）。",-1)),e[6]||(e[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：处理前拟合差时，初学者要么硬跑（把拟合噪声当缺口），要么以为「效应是零」。正确读法是第三种——对照库张不出 \\(\\hat Y_1(0)\\)，反事实根本没造出来；这是设计层面的失败结论，出路是换对照库、加长 \\(T_0\\) 或换设计，不是换一个估计量硬算。")],-1)),(t(),r(l,null,{default:a(()=>[o(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E6%9C%AC%E5%90%88%E6%88%90%3A%20%E5%87%B8%E6%9D%83%E9%87%8D%E8%B4%B4%E5%A4%84%E7%90%86%E5%89%8D%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20B1%5B%22%E5%81%8F%E5%B7%AE%E6%BA%90%201%3A%20T0%20%E7%9F%AD%2C%20%E6%8B%9F%E5%90%88%E9%9D%A0%E8%AE%B0%E5%BF%86%E5%99%AA%E5%A3%B0%22%5D%0A%20%20BASE%20--%3E%20B2%5B%22%E5%81%8F%E5%B7%AE%E6%BA%90%202%3A%20%E5%87%B8%E5%8C%85%E8%BE%B9%E7%BC%98%2C%20%E6%9D%83%E9%87%8D%E5%8E%8B%E4%B8%8D%E6%BB%A1%22%5D%0A%20%20B1%20--%3E%20FIX1%5B%22synthetic%20DiD%3A%20%E6%97%B6%E9%97%B4%E6%9D%83%E9%87%8D%E5%90%B8%E6%94%B6%22%5D%0A%20%20B2%20--%3E%20FIX2%5B%22augmented%3A%20%E5%9B%9E%E5%BD%92%E5%9E%AB%E5%B1%82%E6%A0%A1%E6%AD%A3%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20FIX1%20--%3E%20C1%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E8%A6%81%E5%A4%9A%E4%B8%AA%E5%A4%84%E7%90%86%E5%8D%95%E4%BD%8D%22%5D%0A%20%20FIX2%20--%3E%20C2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E5%A4%96%E6%8E%A8%E8%A2%AB%E9%87%8D%E6%96%B0%E8%AF%B7%E5%9B%9E%E6%9D%A5%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=i('<p>上图回答的问题是「两个修正各补哪个洞、各付什么代价」：方法图画的是实施顺序（何时停、何时换修正），这张把偏差来源与修正方法对号入座——synthetic DiD 吸收 \\(T_0\\) 短的过拟合，augmented 吸收凸包边缘的权重不满，两者都不是无条件升级，而是基本装置吃紧时的定向补丁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理合格对照库都凑不出的场景，也不把合成对照写成万能 DiD 替身：干预效应小而短、处理后噪声大时，排位检验没有功效；同时冲击不可排除时设计整体失效，修正方法救不了。交错多单位的大面板是接下来事件研究与交错 DiD 两课的地盘；外推成一般政策的范围问题留给本课程后段。</p><p>后课默认：少处理单位先过可行判据，再谈修正与推断；「合成得像」是前提，不是结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可行判据四条：拟合好、凸包内、无同时冲击、\\(T_0\\) 相对预测变量够长。</li><li>augmented 修正权重不满，synthetic DiD 在拟合与平行趋势之间插值；各有代价。</li><li>单单位推断靠安慰剂排位，不是常规标准误。</li><li>拟合优度是前提证明；前提塌了设计即失败，不是效应为零。</li><li>出处：Abadie, <em>JEL</em> 2021；Abadie, Diamond and Hainmueller, <em>JASA</em> 2010；Arkhangelsky 等, <em>AER</em> 2021；Ben-Michael, Feller and Rothstein。</li></ul>',6))])}const g=s(d,[["render",p]]);export{_ as __pageData,g as default};
